SELECT id, supplier_name, country, city, rating, SUM(rating) OVER (ORDER BY rating ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share, LAST_VALUE(city, TRUE) OVER (PARTITION BY country ORDER BY rating ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city FROM suppliers
